# Extract key sections from each guide spec for tailoring
import re

def extract_parts(content):
    parts = {}
    part_pattern = r'(PART \d+\s+\w+)'
    matches = list(re.finditer(part_pattern, content))
    for i, m in enumerate(matches):
        start = m.end()
        end = matches[i+1].start() if i+1 < len(matches) else len(content)
        parts[m.group(1).strip()] = content[start:end].strip()
    return parts

specs_parsed = {}
for name in ['26_05_73', '26_20_00', '26_24_13', '26_32_15', '26_36_23', '26_51_00']:
    with open(f'/tmp/full_{name}.txt', 'r') as f:
        content = f.read()

    # Get section header and references
    header_end = content.find('PART 1')
    header = content[:header_end].strip()
    parts = extract_parts(content)
    specs_parsed[name] = {'header': header, 'parts': parts}
    print(f"{name}: Header={len(header)}, Parts={list(parts.keys())}")

